function L({registerIndicator:y,sourceValues:N,nulls:s}){y({id:"oa-spbf",name:"Ehlers Super Passband Filter (SPBF)",category:"Filters",placement:"pane",inputs:[{key:"shortPeriod",type:"number",label:"Short Period",default:40,min:1,max:5e3,step:1,tooltip:"Short EMA period (alpha = 5/period)"},{key:"longPeriod",type:"number",label:"Long Period",default:60,min:1,max:5e3,step:1,tooltip:"Long EMA period (alpha = 5/period)"},{key:"rmsPeriod",type:"number",label:"RMS Period",default:50,min:1,max:5e3,step:1,tooltip:"RMS averaging period for trigger envelope"},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"pb",type:"line",title:"SuperPB",style:{color:"#2196f3",lineWidth:2}},{key:"rmsUpper",type:"line",title:"+RMS",style:{color:"#ff5252",lineWidth:1}},{key:"rmsLower",type:"line",title:"-RMS",style:{color:"#4caf50",lineWidth:1}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(t,l){const P=Math.max(1,Math.floor(Number(l.shortPeriod)||40)),M=Math.max(1,Math.floor(Number(l.longPeriod)||60)),a=Math.max(1,Math.floor(Number(l.rmsPeriod)||50)),n=N(t,l.source??"close"),o=5/P,i=5/M,g=o-i,S=i*(1-o)-o*(1-i),F=1-o+(1-i),x=(1-o)*(1-i),r=new Array(t.length).fill(NaN),d=new Array(t.length).fill(NaN),u=new Array(t.length).fill(NaN),c=new Array(t.length).fill(0);let p=0;for(let e=0;e<t.length;e++){const h=Number.isFinite(n[e])?n[e]:NaN,m=e>0&&Number.isFinite(n[e-1])?n[e-1]:NaN,b=Number.isFinite(h)?h:m,k=Number.isFinite(m)?m:b,w=e>0&&Number.isFinite(r[e-1])?r[e-1]:0,A=e>1&&Number.isFinite(r[e-2])?r[e-2]:0;r[e]=g*b+S*k+F*w-x*A,c[e]=Number.isFinite(r[e])?r[e]*r[e]:0,p+=c[e],e>=a&&(p-=c[e-a]);const f=Math.sqrt(Math.max(0,p)/a);d[e]=f,u[e]=-f}return{pb:s(r),rmsUpper:s(d),rmsLower:s(u)}}})}export{L as default};
